mapper.select:



        AND (
            LOWER(ct.cause_standard) LIKE CONCAT('%', LOWER(#{query}), '%')
            OR LOWER(ct.effect_standard) LIKE CONCAT('%', LOWER(#{query}), '%')
        )


        AND EXISTS (
            SELECT 1
            FROM work_topic wt_filter
            WHERE wt_filter.work_id = pct.paper_id
            AND wt_filter.subfield_name IN

                #{subfield}

        )


GROUP BY ct.claim_id, ct.cause_standard, ct.effect_standard
HAVING COUNT(*) >= #{minRecordCount}
   AND COUNT(DISTINCT NULLIF(pct.causal_inference_method, '')) >= #{minDiversity}

   AND COUNT(DISTINCT pct.paper_id) >= #{minPaperCount}

ORDER BY COUNT(*) DESC, COUNT(DISTINCT pct.paper_id) DESC, ct.claim_id ASC
LIMIT #{limit}


WHERE ct.cause_standard = #{cause}
  AND ct.effect_standard = #{effect}
GROUP BY ct.claim_id, ct.cause_standard, ct.effect_standard
ORDER BY COUNT(DISTINCT pct.record_id) DESC, ct.claim_id ASC
LIMIT 1


WHERE ct.cause_standard = #{variable}
GROUP BY ct.claim_id, ct.cause_standard, ct.effect_standard
ORDER BY COUNT(*) DESC, ct.effect_standard ASC
LIMIT #{limit}


WHERE ct.effect_standard = #{variable}
GROUP BY ct.claim_id, ct.cause_standard, ct.effect_standard
ORDER BY COUNT(*) DESC, ct.cause_standard ASC
LIMIT #{limit}


WHERE ct.claim_id = #{claimId}
ORDER BY w.publication_year DESC NULLS LAST, pct.record_id DESC
LIMIT #{limit}


WHERE ct.cause_standard = #{cause}
  AND ct.effect_standard = #{effect}
ORDER BY w.publication_year DESC NULLS LAST, pct.record_id DESC
LIMIT #{limit}

SELECT wt.subfield_name AS subfield, wt.topic_name AS topic, COUNT(DISTINCT pct.record_id) AS claim_record_count FROM paper_claim_table pct JOIN work_topic wt ON wt.work_id = pct.paper_id WHERE wt.subfield_name IN
#{subfield}
AND wt.topic_name IN
#{topic}
GROUP BY wt.subfield_name, wt.topic_name ORDER BY subfield ASC, topic ASC

WITH field_claims AS ( SELECT wt.subfield_name AS subfield, pct.record_id, pct.paper_id, pct.claim_id, ct.cause_standard, ct.effect_standard FROM paper_claim_table pct JOIN claim_table ct ON ct.claim_id = pct.claim_id JOIN work_topic wt ON wt.work_id = pct.paper_id WHERE (
wt.subfield_name = #{subfield}
) ) SELECT fc.subfield, COUNT(DISTINCT fc.paper_id) AS paper_count, COUNT(DISTINCT fc.record_id) AS claim_record_count, COUNT(DISTINCT fc.claim_id) AS standard_claim_count, 0 AS variable_count FROM field_claims fc GROUP BY fc.subfield ORDER BY fc.subfield ASC

SELECT wt.subfield_name AS subfield, COALESCE(NULLIF(TRIM(pct.causal_inference_method), ''), '未标注方法') AS method, COUNT(DISTINCT pct.record_id) AS claim_record_count FROM paper_claim_table pct JOIN work_topic wt ON wt.work_id = pct.paper_id WHERE wt.subfield_name IN
#{subfield}
GROUP BY wt.subfield_name, COALESCE(NULLIF(TRIM(pct.causal_inference_method), ''), '未标注方法') ORDER BY subfield ASC, claim_record_count DESC, method ASC

WITH field_variables AS ( SELECT wt.subfield_name AS subfield, ct.cause_standard AS variable, pct.record_id FROM paper_claim_table pct JOIN claim_table ct ON ct.claim_id = pct.claim_id JOIN work_topic wt ON wt.work_id = pct.paper_id WHERE wt.subfield_name IN
#{subfield}
UNION ALL SELECT wt.subfield_name AS subfield, ct.effect_standard AS variable, pct.record_id FROM paper_claim_table pct JOIN claim_table ct ON ct.claim_id = pct.claim_id JOIN work_topic wt ON wt.work_id = pct.paper_id WHERE wt.subfield_name IN
#{subfield}
) SELECT subfield, variable, COUNT(DISTINCT record_id) AS claim_record_count FROM field_variables GROUP BY subfield, variable ORDER BY subfield ASC, claim_record_count DESC, variable ASC

WITH global_relations AS ( SELECT ct.claim_id, COUNT(DISTINCT pct.record_id) AS global_claim_record_count, COUNT(DISTINCT pct.paper_id) AS global_paper_count, COUNT(DISTINCT NULLIF(TRIM(pct.causal_inference_method), '')) AS global_method_count FROM paper_claim_table pct JOIN claim_table ct ON ct.claim_id = pct.claim_id GROUP BY ct.claim_id ), field_relations AS ( SELECT wt.subfield_name AS subfield, ct.claim_id, ct.cause_standard AS cause, ct.effect_standard AS effect, COUNT(DISTINCT pct.record_id) AS claim_record_count, COUNT(DISTINCT pct.paper_id) AS paper_count, COUNT(DISTINCT NULLIF(TRIM(pct.causal_inference_method), '')) AS method_count FROM paper_claim_table pct JOIN claim_table ct ON ct.claim_id = pct.claim_id JOIN work_topic wt ON wt.work_id = pct.paper_id WHERE (
wt.subfield_name = #{subfield}
) GROUP BY wt.subfield_name, ct.claim_id, ct.cause_standard, ct.effect_standard ) SELECT fr.subfield, fr.cause, fr.effect, fr.claim_record_count, fr.paper_count, fr.method_count, gr.global_claim_record_count, gr.global_paper_count, gr.global_method_count FROM field_relations fr JOIN global_relations gr ON gr.claim_id = fr.claim_id ORDER BY fr.subfield ASC, fr.claim_record_count DESC, gr.global_method_count DESC, gr.global_paper_count DESC, fr.cause ASC, fr.effect ASC
